{
  "name": "jev-router-opencode",
  "version": "0.1.0",
  "description": "System 1 model router for OpenCode. A Laya/Jev decision layer classifies each request and selects the downstream System 2 LLM.",
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=20.11"
  },
  "main": "./dist/src/index.js",
  "types": "./dist/src/index.d.ts",
  "bin": {
    "jevrouter": "dist/src/cli/main.js"
  },
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "import": "./dist/src/index.js"
    },
    "./plugin": {
      "types": "./dist/src/opencode/index.d.ts",
      "import": "./dist/src/opencode/index.js"
    }
  },
  "files": [
    "dist/src",
    "examples",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "pretest": "npm run build",
    "test": "node --test \"dist/tests/*.test.js\"",
    "test:watch": "node --test --watch \"dist/tests/*.test.js\"",
    "test:live": "npm run build && node --test --test-timeout=300000 \"dist/tests/live-laya.live.js\"",
    "test:switch": "node tests/opencode-switch.live.mjs",
    "check:names": "npm run build && node .github/check-name-consistency.js",
    "bench": "node examples/bench_laya.mjs",
    "prepublishOnly": "npm run build && node --test \"dist/tests/*.test.js\"",
    "clean": "node -e \"import('node:fs').then(fs => fs.rmSync('dist',{recursive:true,force:true}))\""
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "laya",
    "jev",
    "system-one",
    "router",
    "model-routing",
    "llm"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/husnain381a/JevRouter-for-OpenCode.git"
  },
  "homepage": "https://github.com/husnain381a/JevRouter-for-OpenCode#readme",
  "bugs": {
    "url": "https://github.com/husnain381a/JevRouter-for-OpenCode/issues"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.18",
    "@types/node": "^22.10.2",
    "typescript": "^5.7.2"
  }
}
